CAT = "afspSecurity"; SEG = "SEC"
# AFTR outline 3.1 to 3.3 and 3.8: tax-related identity theft (Pub. 5199), safeguarding taxpayer data
# (Pub. 4557, FTC Safeguards Rule), ITINs (Pub. 1915, Form W-7), Tax Pro Account and Individual Online
# Account (Pubs. 5533 and 5533-A).

